import {Scope} from '../core/EventBus.js';
import {QUESTS,CHARACTERS} from '../data/campaign.js';
import {STAGES,stats} from '../data/stages.js';
import {ARTIFACTS} from '../data/artifacts.js';
import {evaluateCondition} from './QuestManager.js';
const $=id=>document.getElementById(id);
const labels={talk:'안내 데스크에서 대화',inspect:'유물 전시대 관찰',switch:'전시 조명 복구',place:'전시 순서 복원',boss:'유물의 원념 정화',collect:'전시 기록 회수'};
export function questSteps(tree,state={counts:{}},world={choices:{}}){if(tree.all)return tree.all.flatMap(t=>questSteps(t,state,world));if(tree.any)return [{label:'유물을 대하는 마음 선택',value:evaluateCondition(tree,state.counts||{},world)?1:0,total:1}];if(tree.flag)return [{label:'대화 선택 기록',value:evaluateCondition(tree,state.counts||{},world)?1:0,total:1}];return [{label:tree.event==='collect'&&/^archive-[0-5]$/.test(tree.target)?ARTIFACTS[Number(tree.target.at(-1))].short+' 기록 회수':labels[tree.event]||'단서 기록',value:Math.min(tree.count||1,state.counts?.[tree.id]||0),total:tree.count||1}];}
export function questPercent(q,state,world){if(state?.done)return 100;const steps=questSteps(q.condition,state,world);return Math.round(steps.reduce((n,s)=>n+s.value/s.total,0)/steps.length*100);}
export class HubUI {
 constructor(rpg){this.rpg=rpg;this.scope=null;this.motionTimer=null;}
 dispose(){this.scope?.dispose();this.scope=null;clearTimeout(this.motionTimer);}
 render(){const r=this.rpg,g=r.game,active=r.active,c=active?r.character:CHARACTERS[0],s=stats(g.save),pending=active?QUESTS.filter(q=>r.quests.eligible(q)&&!r.data.quests[q.id]?.done):[QUESTS[0]],tracked=pending.find(q=>q.id===r.data?.world.choices.trackedQuest)||pending[0],restored=active?g.save.restored.reduce((a,b)=>a+b,0)/6:0;
  g.view('hub',`<section class="reception-hub" aria-label="부천시립박물관 안내 데스크 맵"><button id="desk-main-back" class="desk-main-back">← 메인 로비</button><div class="hub-world" id="hub-world"><div class="hub-map-shade"></div><button id="hub-curator" class="curator-desk-npc" aria-label="도윤 선임 학예사와 대화"><b>!</b><img src="./assets/curator-doyun-sprite.png" alt="중후한 남성 학예사 도윤"><span>도윤 · 선임 학예사</span></button><button class="hub-location location-desk" id="hub-desk"><span class="npc-quest">!</span><strong>안내 데스크</strong><small>점동이 · 의뢰와 보고</small></button><button class="hub-location location-workshop" id="hub-workshop"><strong>유물 복원대</strong><small>잃어버린 형태를 잇는 곳</small></button><button class="hub-location location-exhibition" id="hub-exhibition"><strong>밤의 전시실</strong><small>유물의 기억 속으로</small></button><div id="hub-avatar" class="hub-avatar" role="img" aria-label="${c.name} · 바닥을 눌러 이동"><div class="hub-player-sheet" style="background-image:url('./assets/${c.art}')"></div><span>${c.name}</span></div><div class="hub-ground-hint">바닥을 눌러 이동 · 전시 공간을 눌러 이용</div></div><header class="hub-header"><div class="hub-profile"><div class="hub-profile-symbol">☾</div><div><small>${active?`학예사 · ${r.data.cycle}회차`:'새로운 학예사를 기다립니다'}</small><strong>${active?c.name:'여월의 밤'}</strong><span>${active?`생명 ${s.hp+c.hp} · 정화력 ${s.attack+c.attack}`:'부천시립박물관의 기억을 잇는 모험'}</span></div></div><div class="hub-place-title"><small>BUCHEON MUSEUM · DAY</small><h1>안내 데스크</h1></div><button id="hub-settings" class="hub-settings" aria-label="환경설정">⚙ <span>환경설정</span></button></header><aside class="hub-quest-panel"><div class="hub-panel-title"><span>✧</span><h2>받은 의뢰</h2><small>${active?pending.length:'—'}</small></div>${tracked?`<article class="hub-tracked-quest"><small>${active?'진행 중 · 유물 조사':'첫 번째 이야기'}</small><h3>${tracked.name}</h3><p>${tracked.description}</p>${active?`<ul>${questSteps(tracked.condition,r.data.quests[tracked.id],r.data.world).map(step=>`<li class="${step.value>=step.total?'complete':''}"><span>${step.value>=step.total?'✓':'◇'} ${step.label}</span><b>${step.value}/${step.total}</b></li>`).join('')}</ul><div class="bar"><i style="width:${questPercent(tracked,r.data.quests[tracked.id],r.data.world)}%"></i></div>`:'<p class="hub-start-hint">학예사를 등록하면 의뢰가 시작됩니다.<br>저장된 기록은 환경설정에서 이어갈 수 있어요.</p>'}<button id="hub-primary" class="primary">${active?'의뢰 일지 열기':'학예사 등록 · 새 여정'}</button></article>`:'<article class="hub-tracked-quest"><h3>모든 의뢰를 마쳤습니다</h3><p>남은 유물을 복원하거나 다음 회차를 준비하세요.</p><button id="hub-primary">복원대 열기</button></article>'}<div class="hub-restore-summary"><span>박물관 복원도</span><b>${Math.round(restored)}%</b><div class="bar"><i style="width:${restored}%"></i></div></div></aside><div class="hub-companion"><span>♨</span><p><b>점동이</b>${active?'“물건 하나마다 만든 이의 마음이 있지. 오늘 받은 의뢰부터 살펴보자고.”':'“어서 와. 여긴 기억을 잃은 유물들이 다시 이야기를 찾는 곳이여.”'}</p></div><nav class="hub-dock" aria-label="박물관 주요 시설">${[['restore','♨','유물 복원대','흙과 기억을 잇다'],['quests','▤','의뢰 게시판','받은 이야기 확인'],['archive','◇','유물 도록','전시 자료 살펴보기'],['map','⌘','전시실 지도','발견한 길과 전시대'],['bag','▣','가방 · 장착','복원 유물 관리'],['adventure','☾','밤의 전시실','탐험 시작']].map(([id,icon,title,sub])=>`<button id="hub-${id}" class="${id==='adventure'?'hub-adventure':''}"><span>${icon}</span><strong>${title}</strong><small>${sub}</small></button>`).join('')}</nav><span class="hub-save-note" id="rpg-status" role="status">${active?`슬롯 ${r.slot} · 안내 데스크 자동 저장`:'부천시립박물관에서 시작하는 여월의 밤'}</span></section>`);
  this.scope=new Scope();const guard=action=>{if(active)action();else this.registrationNotice();};
  $('desk-main-back').onclick=()=>r.home();$('hub-settings').onclick=()=>g.settings();$('hub-primary').onclick=()=>active?(tracked?r.journal():g.restoration()):g.boot();
  $('hub-curator').onclick=()=>r.conversation.desk();$('hub-desk').onclick=()=>guard(()=>r.talk('jeomdong'));$('hub-workshop').onclick=$('hub-restore').onclick=()=>guard(()=>g.restoration());$('hub-exhibition').onclick=$('hub-adventure').onclick=()=>active?g.exhibitions():g.boot();$('hub-quests').onclick=()=>guard(()=>r.journal());$('hub-archive').onclick=()=>this.catalog();$('hub-map').onclick=()=>guard(()=>r.showMap());$('hub-bag').onclick=()=>guard(()=>r.equipment());
  const world=$('hub-world'),move=e=>{if(e.target.closest?.('button'))return;const rect=world.getBoundingClientRect();const x=Math.max(28,Math.min(67,(e.clientX-rect.left)/rect.width*100)),y=Math.max(52,Math.min(77,(e.clientY-rect.top)/rect.height*100));const avatar=$('hub-avatar');avatar.style.left=x+'%';avatar.style.top=y+'%';avatar.classList.add('walking');clearTimeout(this.motionTimer);this.motionTimer=setTimeout(()=>avatar.classList.remove('walking'),550);};world.addEventListener('pointerdown',move);this.scope.own(()=>world.removeEventListener('pointerdown',move));
 }
 registrationNotice(){this.rpg.game.dialog('<h2>안내 데스크에 학예사를 등록해 주세요</h2><p>새 여정을 시작하면 유물 복원과 의뢰를 이용할 수 있습니다. 저장된 기록은 환경설정에서 이어갈 수 있어요.</p><div class="actions"><button id="register-from-hub" class="primary">학예사 등록</button><button id="settings-from-hub">환경설정</button><button data-close>돌아가기</button></div>');$('register-from-hub').onclick=()=>this.rpg.game.boot();$('settings-from-hub').onclick=()=>this.rpg.game.settings();}
 catalog(){this.rpg.game.dialog(`<small>MUSEUM COLLECTION NOTES</small><h2>유물에서 시작하는 이야기</h2><button id="catalog-research">학예 연구 일지 · 관람객 단서</button><div class="artifact-catalog">${ARTIFACTS.map((a,i)=>`<article><div class="artifact-case-art" style="--case-x:${((i+6)%4)/3*100}%;--case-y:${Math.floor((i+6)/4)/2*100}%"></div><h3>${a.title}</h3><p>${a.fact}</p><small>${STAGES[i].name}</small></article>`).join('')}</div><p class="source-note">전시 주제를 바탕으로 재구성한 게임 일러스트와 이야기입니다. <a href="https://www.bcmuseum.or.kr/ko/pages/exhi_permanent" target="_blank" rel="noopener">부천시립박물관 상설전시 안내 ↗</a></p><button data-close>안내 데스크로</button>`);$('catalog-research').onclick=()=>this.rpg.active?this.rpg.game.journal():this.registrationNotice();}
}
